-- PostgreSQL. Allowances and charges on a SalesInvoice for AllowanceCharges=InvoiceAllowanceCharge:IsCharge:BaseAmount:Percentage:Amount:SalesInvoiceId (the InvoiceSystem copy).
CREATE TABLE IF NOT EXISTS "InvoiceAllowanceCharge" (
    "InvoiceAllowanceChargeId" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "SalesInvoiceId" integer NOT NULL REFERENCES "SalesInvoice" ("SalesInvoiceId"),
    "IsCharge" boolean NOT NULL DEFAULT false,
    "ReasonCode" varchar(10) NULL,
    "BaseAmount" numeric(18, 2) NULL,
    "Percentage" numeric(9, 4) NULL,
    "Amount" numeric(18, 2) NOT NULL
);
